def retain_existing_images(apps, schema_editor):
    Photo = apps.get_model('demo_store', 'ProductPhoto')
    Version = apps.get_model('demo_store', 'ProductPhotoVersion')
    Item = apps.get_model('demo_store', 'StoreOrderItem')
    db = schema_editor.connection.alias
    for photo in Photo.objects.using(db).iterator():
        Version.objects.using(db).create(photo_id=photo.pk, version=1, bucket=photo.bucket,
                                       key=photo.key, width=photo.width, height=photo.height)
    for item in Item.objects.using(db).select_related('variant__product').iterator():
        if item.variant_id:
            photos = Photo.objects.using(db).filter(product_id=item.variant.product_id)
            photo = photos.filter(variant_id=item.variant_id).first() or photos.filter(variant__isnull=True).first()
            if photo:
                item.image_bucket, item.image_key = photo.bucket, photo.key
                item.image_alt = photo.alt_text or item.product_name
                item.save(using=db, update_fields=['image_bucket', 'image_key', 'image_alt'])


